function survivingHealths(positions: number[], healths: number[], directions: string): number[] {
  const h = healths.slice();
  let alive = positions.map((_, i) => i).sort((a, b) => positions[a] - positions[b]);
  for (;;) {
    let k = 0;
    while (k + 1 < alive.length && !(directions[alive[k]] === "R" && directions[alive[k + 1]] === "L")) k++;
    if (k + 1 >= alive.length) break;
    const a = alive[k], b = alive[k + 1];
    if (h[a] < h[b]) { h[a] = 0; h[b]--; }
    else if (h[a] > h[b]) { h[b] = 0; h[a]--; }
    else h[a] = h[b] = 0;
    alive = alive.filter(i => h[i] > 0);
  }
  return h.filter(x => x > 0);
}

