class Solution:
    def survivingHealths(self, positions: List[int], healths: List[int], directions: str) -> List[int]:
        h = healths[:]
        alive = sorted(range(len(positions)), key=lambda i: positions[i])
        while True:
            k = 0
            while k + 1 < len(alive) and not (directions[alive[k]] == "R" and directions[alive[k + 1]] == "L"):
                k += 1
            if k + 1 >= len(alive):
                break
            a, b = alive[k], alive[k + 1]
            if h[a] < h[b]:
                h[a] = 0
                h[b] -= 1
            elif h[a] > h[b]:
                h[b] = 0
                h[a] -= 1
            else:
                h[a] = h[b] = 0
            alive = [i for i in alive if h[i] > 0]
        return [x for x in h if x > 0]

