function survivingHealths(positions: number[], healths: number[], directions: string): number[] {
  const n = positions.length, h = healths.slice();
  const order = Array.from({ length: n }, (_, i) => i).sort((a, b) => positions[a] - positions[b]);
  const stack: number[] = []; // indexes of right-movers still alive
  for (const i of order) {
    if (directions[i] === "R") { stack.push(i); continue; }
    while (stack.length && h[i] > 0) {
      const j = stack[stack.length - 1];
      if (h[j] < h[i]) { h[j] = 0; stack.pop(); h[i]--; }
      else if (h[j] > h[i]) { h[j]--; h[i] = 0; }
      else { h[j] = 0; h[i] = 0; stack.pop(); }
    }
  }
  return h.filter(x => x > 0);
}

