    while (stack.length && h[i] > 0) {
      const j = stack[stack.length - 1];
      if (h[j] < h[i]) {
        h[j] = 0;
        stack.pop();
        h[i]--;
      } else if (h[j] > h[i]) {
        h[j]--;
        h[i] = 0;
      } else {
        h[j] = 0;
        h[i] = 0;
        stack.pop();
      }
    }
  }
  return h.filter((x) => x > 0);
}
